from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ServiceMeshRegistry

class ServiceMeshHealthDiagnosticView(APIView):
    # Restrict internal service mesh diagnostics strictly to platform admins
    permission_classes = [permissions.IsAdminUser]

    def get(self, request, service_name):
        svc = ServiceMeshRegistry.objects.filter(service_name=service_name).first()
        if not svc:
            return Response({"error": "Service not found"}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            "service": svc.service_name,
            "internal_rpc_host": svc.rpc_endpoint,
            "grpc_port": svc.grpc_port,
            "k8s_namespace": svc.namespace,
            "health": svc.status
        }, status=status.HTTP_200_OK)
